import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('SpaceGrotesk');

// Module-level font loading
const { fontFamily } = loadFont("normal", {
  weights: ["400", "700"],
  subsets: ["latin"],
});



export type PriceGoalAnimationProps = Record<string, any>;

const PriceGoalAnimation: React.FC<PriceGoalAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 6,
  startPrice = "37",
  endPrice = "97",
  currencySymbol = "$",
  lineColor = "#ffffff",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Normalizing standard 30fps animation speeds
  const relativeFrame = frame * (30 / fps);

  // Animations configuration
  // 1. Start Price Entrance (Frame 0 to 18)
  const startPriceSpring = spring({
    frame: relativeFrame,
    fps: 30,
    config: { damping: 12, mass: 0.6, stiffness: 100 },
  });

  // 2. Dash line and Bullseye entrance (Frame 12 to 30)
  const dashLineSpring = spring({
    frame: relativeFrame - 12,
    fps: 30,
    config: { damping: 15, stiffness: 120 },
  });

  const bullseyeSpring = spring({
    frame: relativeFrame - 18,
    fps: 30,
    config: { damping: 10, stiffness: 100 },
  });

  // 3. Arrow Reveal (Frame 35 to 52)
  const arrowProgress = interpolate(relativeFrame, [35, 52], [0, 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const arrowOpacity = interpolate(relativeFrame, [35, 38], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 4. End Price Entrance (Frame 48 to 68)
  const endPriceSpring = spring({
    frame: relativeFrame - 48,
    fps: 30,
    config: { damping: 12, mass: 0.6, stiffness: 100 },
  });

  // Left Price dim & scaling when target is hit
  const startPriceFade = interpolate(relativeFrame, [48, 60], [1, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const startPriceScaleDown = interpolate(relativeFrame, [48, 60], [1, 0.95], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const startPriceScale = startPriceSpring * startPriceScaleDown;
  const startPriceOpacity = startPriceSpring * startPriceFade;

  const endPriceScale = endPriceSpring;
  const endPriceOpacity = endPriceSpring;

  // Coordinate Calculations
  const dashLineHeight = height * 0.55;
  const dashLineYStart = height * 0.15;
  const bullseyeY = height * 0.65;
  const startPriceFontSize = height * 0.24;
  const currencyFontSize = height * 0.08;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, transition: "none" }}>
      {/* Background/Center SVG layer containing the line, bullseye & arrow */}
      <svg
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        <defs>
          <clipPath id="arrow-clip">
            <rect
              x={width * 0.38}
              y={height * 0.4}
              width={(width * 0.24) * (arrowProgress / 100)}
              height={height * 0.2}
            />
          </clipPath>
        </defs>

        {/* Central dashed line */}
        <line
          x1={width * 0.5}
          y1={dashLineYStart}
          x2={width * 0.5}
          y2={dashLineYStart + dashLineHeight * dashLineSpring}
          stroke={lineColor}
          strokeWidth={3}
          strokeDasharray="10 10"
          style={{ transition: "none" }}
        />

        {/* Bullseye Target */}
        <g
          transform={`translate(${width * 0.5}, ${bullseyeY}) scale(${bullseyeSpring})`}
          style={{ transition: "none" }}
        >
          {/* Outer circle */}
          <circle r={48} fill={backgroundColor} stroke={lineColor} strokeWidth={6} />
          {/* Middle Ring */}
          <circle r={28} fill="transparent" stroke={lineColor} strokeWidth={6} />
          {/* Inner Dot */}
          <circle r={10} fill={lineColor} />
        </g>

        {/* Arrow element */}
        <g clipPath="url(#arrow-clip)" style={{ opacity: arrowOpacity, transition: "none" }}>
          <line
            x1={width * 0.39}
            y1={height * 0.5}
            x2={width * 0.59}
            y2={height * 0.5}
            stroke={lineColor}
            strokeWidth={6}
            strokeLinecap="round"
          />
          <path
            d={`M ${width * 0.59 - 18} ${height * 0.5 - 15} L ${width * 0.59} ${height * 0.5} L ${width * 0.59 - 18} ${height * 0.5 + 15}`}
            fill="none"
            stroke={lineColor}
            strokeWidth={6}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </g>
      </svg>

      {/* Start Price Container */}
      <div
        style={{
          position: "absolute",
          left: width * 0.12,
          top: height * 0.3,
          width: width * 0.28,
          height: height * 0.35,
          display: "flex",
          flexDirection: "row",
          alignItems: "flex-start",
          justifyContent: "center",
          color: textColor,
          transform: `scale(${startPriceScale})`,
          opacity: startPriceOpacity,
          transition: "none",
        }}
      >
        <span
          style={{
            fontFamily,
            fontWeight: 700,
            fontSize: currencyFontSize,
            lineHeight: 1,
            marginTop: height * 0.02,
            marginRight: 10,
            transition: "none",
          }}
        >
          {currencySymbol}
        </span>
        <span
          style={{
            fontFamily,
            fontWeight: 700,
            fontSize: startPriceFontSize,
            lineHeight: 1,
            letterSpacing: "-4px",
            transition: "none",
          }}
        >
          {startPrice}
        </span>
      </div>

      {/* End Price Container */}
      <div
        style={{
          position: "absolute",
          left: width * 0.6,
          top: height * 0.3,
          width: width * 0.28,
          height: height * 0.35,
          display: "flex",
          flexDirection: "row",
          alignItems: "flex-start",
          justifyContent: "center",
          color: textColor,
          transform: `scale(${endPriceScale})`,
          opacity: endPriceOpacity,
          transition: "none",
        }}
      >
        <span
          style={{
            fontFamily,
            fontWeight: 700,
            fontSize: currencyFontSize,
            lineHeight: 1,
            marginTop: height * 0.02,
            marginRight: 10,
            transition: "none",
          }}
        >
          {currencySymbol}
        </span>
        <span
          style={{
            fontFamily,
            fontWeight: 700,
            fontSize: startPriceFontSize,
            lineHeight: 1,
            letterSpacing: "-4px",
            transition: "none",
          }}
        >
          {endPrice}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default PriceGoalAnimation;